def transform(grid):
 h,w=len(grid),len(grid[0]); from collections import Counter
 bg=Counter(v for row in grid for v in row).most_common(1)[0][0]
 mark=next(v for v in range(10) if v!=bg and any(v in row for row in grid))
 pts=[(r,c) for r in range(h) for c in range(w) if grid[r][c]==mark]
 r0,r1=min(r for r,c in pts),max(r for r,c in pts); c0,c1=min(c for r,c in pts),max(c for r,c in pts)
 out=[row[:] for row in grid]
 def paint(r,c):
